import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Random;

public class Main {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ' && c != -1) c = readByte();
            if (c == -1) return -1;
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sgn;
        }

        public long nextLong() {
            int c = readByte();
            while (c <= ' ' && c != -1) c = readByte();
            if (c == -1) return -1;
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            long res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sgn;
        }
    }

    static class ValueIndex {
        long[] distinctVals;
        int[] head;
        int[] tail;
        int[] pos;

        public ValueIndex(long[] rawVals, int n) {
            long[] packed = new long[n];
            for (int i = 0; i < n; i++) {
                packed[i] = (rawVals[i] << 32) | (i + 1); // 1-based index
            }
            shuffle(packed);
            Arrays.sort(packed);

            int countDistinct = 0;
            for (int i = 0; i < n; i++) {
                if (i == 0 || (packed[i] >>> 32) != (packed[i - 1] >>> 32)) {
                    countDistinct++;
                }
            }

            distinctVals = new long[countDistinct];
            head = new int[countDistinct];
            tail = new int[countDistinct];
            pos = new int[n];

            int dIdx = -1;
            for (int i = 0; i < n; i++) {
                long val = packed[i] >>> 32;
                int p = (int) (packed[i] & 0xFFFFFFFFL);
                pos[i] = p;

                if (i == 0 || val != (packed[i - 1] >>> 32)) {
                    dIdx++;
                    distinctVals[dIdx] = val;
                    head[dIdx] = i;
                }
                tail[dIdx] = i;
            }
        }

        private static void shuffle(long[] arr) {
            Random rnd = new Random(42);
            for (int i = arr.length - 1; i > 0; i--) {
                int j = rnd.nextInt(i + 1);
                long tmp = arr[i];
                arr[i] = arr[j];
                arr[j] = tmp;
            }
        }

        public int countInRange(long val, int low, int high) {
            if (low > high) return 0;
            int idx = Arrays.binarySearch(distinctVals, val);
            if (idx < 0) return 0;

            int start = head[idx];
            int end = tail[idx];

            int l = lowerBound(pos, start, end, low);
            int r = upperBound(pos, start, end, high);
            return Math.max(0, r - l);
        }

        private int lowerBound(int[] arr, int start, int end, int target) {
            int l = start, r = end;
            int ans = end + 1;
            while (l <= r) {
                int mid = (l + r) >>> 1;
                if (arr[mid] >= target) {
                    ans = mid;
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }
            return ans;
        }

        private int upperBound(int[] arr, int start, int end, int target) {
            int l = start, r = end;
            int ans = end + 1;
            while (l <= r) {
                int mid = (l + r) >>> 1;
                if (arr[mid] > target) {
                    ans = mid;
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }
            return ans;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        int N = sc.nextInt();
        if (N == -1) return;
        int Q = sc.nextInt();
        long K = sc.nextLong();

        long[] A = new long[N + 1];
        long[] U = new long[N];
        long[] V = new long[N];

        long OFFSET_V = 1_000_000_000L;

        for (int i = 1; i <= N; i++) {
            A[i] = sc.nextLong();
            U[i - 1] = A[i] + i;
            V[i - 1] = A[i] - i + OFFSET_V;
        }

        ValueIndex indexU = new ValueIndex(U, N);
        ValueIndex indexV = new ValueIndex(V, N);

        int[] D = new int[Q + 1];
        boolean[] isCollapsed = new boolean[N + 1];
        for (int t = 1; t <= Q; t++) {
            D[t] = sc.nextInt();
            isCollapsed[D[t]] = true;
        }

        int[] remaining = new int[N - Q];
        int remCount = 0;
        for (int i = 1; i <= N; i++) {
            if (!isCollapsed[i]) {
                remaining[remCount++] = i;
            }
        }

        int[] order = new int[N + 1];
        int ordPtr = 1;
        for (int i = 0; i < remCount; i++) {
            order[ordPtr++] = remaining[i];
        }
        for (int t = Q; t >= 1; t--) {
            order[ordPtr++] = D[t];
        }

        boolean[] active = new boolean[N + 2];
        int[] leftEnd = new int[N + 2];
        int[] rightEnd = new int[N + 2];

        long[] ansAtMinute = new long[Q + 1];
        long currentPairs = 0;

        for (int step = 1; step <= N; step++) {
            int d = order[step];

            boolean hasL = (d > 1 && active[d - 1]);
            boolean hasR = (d < N && active[d + 1]);

            int L = hasL ? leftEnd[d - 1] : d;
            int R = hasR ? rightEnd[d + 1] : d;

            long added = 0;

            // 1. Pares entre {d} e esquerda [L, d-1]
            if (hasL) {
                int low = (int) Math.max((long) L, d - K);
                int high = d - 1;
                if (low <= high) {
                    added += indexU.countInRange(A[d] + d - K, low, high);
                    added += indexV.countInRange(A[d] - d + K + OFFSET_V, low, high);
                    if (d - K >= L && A[(int) (d - K)] == A[d]) {
                        added--;
                    }
                }
            }

            // 2. Pares entre {d} e direita [d+1, R]
            if (hasR) {
                int low = d + 1;
                int high = (int) Math.min((long) R, d + K);
                if (low <= high) {
                    added += indexU.countInRange(A[d] + d + K, low, high);
                    added += indexV.countInRange(A[d] - d - K + OFFSET_V, low, high);
                    if (d + K <= R && A[(int) (d + K)] == A[d]) {
                        added--;
                    }
                }
            }

            // 3. Pares entre esquerda [L, d-1] e direita [d+1, R]
            if (hasL && hasR) {
                int szL = d - L;
                int szR = R - d;
                if (szL <= szR) {
                    for (int i = L; i <= d - 1; i++) {
                        int low = d + 1;
                        int high = (int) Math.min((long) R, i + K);
                        if (low <= high) {
                            added += indexU.countInRange(A[i] + i + K, low, high);
                            added += indexV.countInRange(A[i] - i - K + OFFSET_V, low, high);
                            if (high == i + K && A[(int) (i + K)] == A[i]) {
                                added--;
                            }
                        }
                    }
                } else {
                    for (int j = d + 1; j <= R; j++) {
                        int low = (int) Math.max((long) L, j - K);
                        int high = d - 1;
                        if (low <= high) {
                            added += indexU.countInRange(A[j] + j - K, low, high);
                            added += indexV.countInRange(A[j] - j + K + OFFSET_V, low, high);
                            if (low == j - K && A[(int) (j - K)] == A[j]) {
                                added--;
                            }
                        }
                    }
                }
            }

            currentPairs += added;

            active[d] = true;
            leftEnd[R] = L;
            rightEnd[L] = R;

            if (step >= remCount) {
                int minIdx = Q - (step - remCount);
                ansAtMinute[minIdx] = currentPairs;
            }
        }

        PrintWriter out = new PrintWriter(System.out);
        for (int t = 0; t <= Q; t++) {
            out.println(ansAtMinute[t]);
        }
        out.flush();
    }
}
